/* Teaching support is deliberately presentation-only: it guides users to the
   declared Software I workflow without changing the governing routing core. */
(() => {
  const isZh=()=>document.documentElement.lang==='zh-Hant';
  const copy=()=>isZh()?{
    title:'教學輔助｜四步自學與立即檢核',
    lead:'依序完成物理條件、執行路由、讀取判讀與確認設計限制。教學提示不會修改 RK4 路由方程或已驗證範圍。',
    start:'載入教學示範', reset:'重新檢核',
    steps:[['1','定義事件入流','選擇三角形或長延時入流；尖峰流量之外，歷線延時與形狀也會影響滯洪量。','mod-inflow'],['2','宣告蓄水與出口','確認 S(H)、初始水位與啟用出口的高程採用相同基準。','mod-storage'],['3','執行並解讀結果','先看質量平衡、最大水位、尖峰出流與寬峰時間判讀。','mod-routing'],['4','判斷是否可設計','只有確認自由出流、且為已驗證的堰流或矩形孔口時，才能進行正式設計搜尋。','mod-optimization']],
    checks:'快速自我檢核（每題約 30 秒）', score:'已答對 {n}/3 題',
    q:[['哪一項最直接決定池內蓄水量的時間變化？',['只有入流尖峰','Qin − Qout','只有池面積'],'Qin − Qout','連續方程以 Qin − Qout 控制蓄水變化。'],['對同一入流尖峰，何者仍可能改變滯洪需求？',['歷線延時與形狀','只有圖表顏色','報告檔名'],'歷線延時與形狀','正確；入流體積、歷線形狀與出口水理都會影響反應。'],['何時不得進行正式設計最佳化？',['已確認自由出流的矩形孔口','使用豎井、圓管或複合出口的研究模式','已驗證的被動堰流'],'使用豎井、圓管或複合出口的研究模式','正確；此類設定僅供研究檢視，須獨立驗證後才能作設計使用。']],
    done:'完成', go:'前往步驟', demo:'已載入三角形示範；接著執行路由並閱讀右側判讀。'
  }:{
    title:'Teaching support | four-step self-learning',
    lead:'Define physical conditions, run the route, interpret the record, and then check design eligibility. Teaching prompts never change the RK4 governing equation or the validated envelope.',
    start:'Load teaching example',reset:'Recheck',
    steps:[['1','Define event inflow','Choose a triangular or long-duration event. Duration and shape, not peak flow alone, affect detention storage.','mod-inflow'],['2','Declare storage and outlets','Use one vertical datum for S(H), the initial level, and every active outlet elevation.','mod-storage'],['3','Run and interpret','Read mass balance, maximum level, peak outflow, and broad-crest timing interpretation first.','mod-routing'],['4','Check design eligibility','Formal design search requires confirmed free discharge and a validated weir or rectangular-opening setting.','mod-optimization']],
    checks:'Quick self-check (about 30 seconds each)',score:'{n}/3 correct',
    q:[['Which term directly controls the time change of pond storage?',['Inflow peak alone','Qin − Qout','Plan area alone'],'Qin − Qout','The continuity equation changes storage by Qin − Qout.'],['For the same inflow peak, what can still change detention demand?',['Hydrograph duration and shape','Chart colour','Report filename'],'Hydrograph duration and shape','Correct. Inflow volume, hydrograph shape, and outlet hydraulics affect the response.'],['When is formal design optimization unavailable?',['Confirmed free-discharge rectangular opening','Research-mode riser, pipe, or composite outlet','Validated passive weir'],'Research-mode riser, pipe, or composite outlet','Correct. These modes are for research inspection until independently validated.']],
    done:'Done',go:'Go to step',demo:'Triangular demonstration loaded. Run routing next and read the interpretation panel.'
  };
  const host=document.querySelector('main.wrap'); if(!host) return;
  const panel=document.createElement('section'); panel.id='teachingAssistant'; panel.className='panel';
  host.insertBefore(panel,host.firstChild);
  const style=document.createElement('style'); style.textContent=`#teachingAssistant{margin-bottom:18px;border-top:5px solid #7c3aed;background:linear-gradient(135deg,#fbfaff,#f3f8ff)}#teachingAssistant h2{font-size:21px}.teach-lead{max-width:900px;color:#38536a;margin:0 0 14px}.teach-top{display:flex;gap:10px;align-items:center;justify-content:space-between;flex-wrap:wrap}.teach-button{border:0;background:#7c3aed;color:#fff;border-radius:5px;padding:9px 13px;font-weight:700;cursor:pointer}.teach-steps{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:16px 0}.teach-step{border:1px solid #d8c9f5;background:#fff;border-radius:7px;padding:12px;min-height:156px}.teach-step b{display:inline-grid;place-items:center;width:25px;height:25px;border-radius:50%;background:#ede9fe;color:#6d28d9;margin-right:6px}.teach-step h3{display:inline;color:#312e81}.teach-step p{font-size:13px;color:#526a78;margin:9px 0 12px}.teach-go{border:1px solid #7c3aed;background:#fff;color:#5b21b6;border-radius:4px;padding:6px 8px;cursor:pointer;font-weight:700}.teach-quiz{border-top:1px solid #d8c9f5;padding-top:14px}.teach-quiz h3{margin:0 0 10px;color:#312e81}.quiz-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.quiz-card{background:#fff;border:1px solid #d8c9f5;border-radius:7px;padding:12px}.quiz-card p{font-weight:700;font-size:14px;margin:0 0 8px}.quiz-card label{font-weight:400;display:flex;gap:7px;align-items:flex-start;cursor:pointer}.quiz-card input{width:auto;margin-top:3px}.quiz-feedback{font-size:13px;margin-top:8px;color:#526a78}.quiz-feedback.ok{color:#166534;font-weight:700}.quiz-feedback.bad{color:#9a5a00}.teach-score{font-size:13px;font-weight:700;color:#5b21b6}@media(max-width:850px){.teach-steps,.quiz-grid{grid-template-columns:1fr}}`; document.head.appendChild(style);
  function render(){const t=copy();panel.innerHTML=`<div class="teach-top"><h2>${t.title}</h2><div><span id="teachScore" class="teach-score">${t.score.replace('{n}','0')}</span> <button id="teachDemo" class="teach-button">${t.start}</button></div></div><p class="teach-lead">${t.lead}</p><div class="teach-steps">${t.steps.map(s=>`<article class="teach-step"><b>${s[0]}</b><h3>${s[1]}</h3><p>${s[2]}</p><button class="teach-go" data-target="${s[3]}">${t.go}</button></article>`).join('')}</div><div class="teach-quiz"><h3>${t.checks}</h3><div class="quiz-grid">${t.q.map((q,i)=>`<article class="quiz-card" data-answer="${q[2]}"><p>${i+1}. ${q[0]}</p>${q[1].map(a=>`<label><input type="radio" name="teach-q${i}" value="${a}">${a}</label>`).join('')}<div class="quiz-feedback" data-note="${q[3]}"></div></article>`).join('')}</div></div>`;
    panel.querySelectorAll('.teach-go').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.target)?.scrollIntoView({behavior:'smooth',block:'start'}));
    panel.querySelector('#teachDemo').onclick=()=>{const set=(id,value)=>{const e=document.getElementById(id);if(e){e.value=value;e.dispatchEvent(new Event('input',{bubbles:true}));}};set('case','tri');document.getElementById('case')?.dispatchEvent(new Event('change',{bubbles:true}));document.getElementById('weirOn').checked=true;document.getElementById('oriOn').checked=false;document.getElementById('freeDischarge').checked=true;document.getElementById('freeDischarge').dispatchEvent(new Event('change',{bubbles:true}));document.getElementById('run')?.click();const note=document.createElement('div');note.className='status';note.textContent=t.demo;panel.appendChild(note);};
    panel.querySelectorAll('input[type=radio]').forEach(input=>input.onchange=()=>{const card=input.closest('.quiz-card'),out=card.querySelector('.quiz-feedback'),correct=input.value===card.dataset.answer;out.textContent=correct?'✓ '+card.dataset.note:'↻ '+card.dataset.note;out.className='quiz-feedback '+(correct?'ok':'bad');const n=[...panel.querySelectorAll('.quiz-card')].filter(c=>c.querySelector('input:checked')?.value===c.dataset.answer).length;panel.querySelector('#teachScore').textContent=t.score.replace('{n}',n);});
  }
  render(); document.getElementById('lang')?.addEventListener('click',()=>setTimeout(render,0));
})();
